function authMessage(message, isError=false){const el=document.getElementById('auth-message');if(el){el.textContent=message||'';el.className=isError?'error':''}}
function showAuth(message=''){document.getElementById('auth').style.display='grid';document.getElementById('app-shell').style.display='none';authMessage(message)}
function showApp(){document.getElementById('auth').style.display='none';document.getElementById('app-shell').style.display='';document.getElementById('user-label').textContent=(currentProfile.display_name||currentUser.email)+' · '+(IS_ADMIN?'Admin':'Kasir');document.getElementById('logout').style.display='inline-flex'}
async function getCloudState(){const {data,error}=await db.rpc('load_fastrex_state');if(error)throw error;revision=Number(data.version);return data.state}
async function refreshCloudState(showToast=false){try{const fresh=await getCloudState();S=fresh;saveBlocked=false;go();if(showToast)toast('Data diperbarui dari cloud')}catch(e){console.error(e);toast('Gagal memuat data cloud')}}
function queueSave(){
  if(!db||!S||!currentUser||saveBlocked)return Promise.resolve();
  const snapshot=JSON.parse(JSON.stringify(S)),generation=saveGeneration;pendingWrites++;
  const task=async()=>{
    try{
      if(saveBlocked||generation!==saveGeneration)return;
      const {data,error}=await db.rpc('save_fastrex_state',{p_state:snapshot,p_expected_version:revision});
      if(error)throw error;
      revision=Number(data);
    }catch(error){
      console.error('Supabase save failed:',error);
      saveBlocked=true;saveGeneration++;
      toast('Konflik/gagal menyimpan. Memuat ulang data cloud…');
      await refreshCloudState(false);
      saveBlocked=false;
      authMessage('Perubahan terakhir gagal disimpan karena data berubah di perangkat lain. Periksa data terbaru lalu ulangi perubahan.',true);
    }finally{
      pendingWrites--;
      if(pendingWrites===0&&remoteUpdate){const update=remoteUpdate;remoteUpdate=null;if(Number(update.version)>revision)await refreshCloudState(true)}
    }
  };
  saveQueue=saveQueue.then(task,task);
  return saveQueue;
}
let saveQueue=Promise.resolve();
async function openApplication(session){
  currentUser=session.user;
  const {data:profile,error:profileError}=await db.from('profiles').select('role,display_name,store_id').eq('id',currentUser.id).single();
  if(profileError||!profile){await db.auth.signOut();showAuth('Akun belum memiliki profil Fastrex. Minta admin menambahkan role di Supabase.');return}
  currentProfile=profile;IS_ADMIN=profile.role==='admin';OWN=IS_ADMIN;
  try{S=await getCloudState()}catch(e){console.error(e);showAuth('Tidak dapat membaca database. Periksa SQL, RLS, dan konfigurasi Supabase.');return}
  showApp();go();
  if(liveChannel)await db.removeChannel(liveChannel);
  liveChannel=db.channel('fastrex:'+currentProfile.store_id,{config:{private:true}}).on('broadcast',{event:'state_changed'},async message=>{
    const payload=message.payload||{};
    if(payload.updated_by===currentUser.id){revision=Math.max(revision,Number(payload.version));return}
    if(pendingWrites){remoteUpdate=payload;return}
    await refreshCloudState(true);
  }).subscribe();
}
async function initFastrexCloud(){
  const cfg=window.FASTREX_SUPABASE;
  if(!cfg||!cfg.url||!cfg.anonKey||cfg.url.includes('PROJECT-REF')||cfg.anonKey.includes('SUPABASE_PUBLISHABLE')){showAuth('Konfigurasi belum diisi. Salin js/config.example.js menjadi js/config.js lalu isi URL dan publishable/anon key Supabase.');return}
  if(!window.supabase||!window.supabase.createClient){showAuth('Library Supabase gagal dimuat. Periksa koneksi internet.');return}
  db=window.supabase.createClient(cfg.url,cfg.anonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,storage:window.sessionStorage}});
  document.getElementById('login-form').addEventListener('submit',async e=>{e.preventDefault();const email=document.getElementById('email').value.trim(),password=document.getElementById('password').value;const btn=document.getElementById('login-submit');btn.disabled=true;authMessage('Memeriksa akun…');const {data,error}=await db.auth.signInWithPassword({email,password});btn.disabled=false;if(error){authMessage('Login gagal: '+error.message,true);return}await openApplication(data.session)});
  document.getElementById('logout').addEventListener('click',async()=>{if(liveChannel)await db.removeChannel(liveChannel);await db.auth.signOut();currentUser=null;currentProfile=null;S=null;showAuth('Kamu sudah keluar dari Fastrex POS.')});
  const {data:{session}}=await db.auth.getSession();if(session)await openApplication(session);else showAuth('Masuk menggunakan akun Fastrex yang dibuat admin.');
  db.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){showAuth('Silakan login kembali.')}else if(event==='TOKEN_REFRESHED'&&session){currentUser=session.user}});
}
initFastrexCloud();
